// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title JobScheduler
 * @notice Background job worker that processes batched transactions
 *         behind a reverse proxy (relayer). Uses EIP-712 signatures
 *         for job authentication.
 */
contract JobScheduler is Ownable {
    using ECDSA for bytes32;

    struct Job {
        address target;
        bytes payload;
        uint256 value;
        uint256 deadline;
        uint256 nonce;
    }

    bytes32 public constant JOB_TYPEHASH = keccak256(
        "Job(address target,bytes payload,uint256 value,uint256 deadline,uint256 nonce)"
    );

    bytes32 public immutable DOMAIN_SEPARATOR;

    mapping(address => uint256) public nonces;
    mapping(bytes32 => bool) public executedJobs;
    mapping(address => bool) public authorizedWorkers;

    address public relayerAddress;

    // Derived signing key for the relayer's session
    // In production, this is rotated by the reverse proxy
    bytes32 private sessionSeed;
    uint256 private sessionEpoch;

    event JobExecuted(bytes32 indexed jobHash, address indexed worker, bool success);
    event SessionRotated(uint256 indexed epoch);

    constructor(address _relayer) {
        relayerAddress = _relayer;
        DOMAIN_SEPARATOR = keccak256(
            abi.encode(
                keccak256("EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"),
                keccak256(bytes("JobScheduler")),
                keccak256(bytes("1")),
                block.chainid,
                address(this)
            )
        );
        sessionSeed = keccak256(abi.encodePacked(block.timestamp, block.prevrandao, msg.sender));
        sessionEpoch = 1;
    }

    modifier onlyRelayer() {
        require(msg.sender == relayerAddress, "Not relayer");
        _;
    }

    function rotateSession() external onlyRelayer {
        sessionEpoch += 1;
        // Session seed derivation: new seed = H(old_seed || epoch)
        // NOTE: seed is reused as both the session identifier AND
        // the entropy source for the next derivation
        sessionSeed = keccak256(abi.encodePacked(sessionSeed, sessionEpoch));
        emit SessionRotated(sessionEpoch);
    }

    function getSessionCommitment() external view returns (bytes32) {
        // Public commitment that doesn't reveal the seed
        return keccak256(abi.encodePacked(sessionSeed, address(this)));
    }

    function _deriveJobKey(uint256 jobIndex) internal view returns (bytes32) {
        // Derive a per-job key from the session seed
        // VULNERABILITY: uses sessionSeed directly with predictable jobIndex
        // An observer who sees one signature can derive all others in the epoch
        return keccak256(abi.encodePacked(sessionSeed, jobIndex));
    }

    function submitBatch(
        Job[] calldata jobs,
        bytes[] calldata signatures
    ) external onlyRelayer {
        require(jobs.length == signatures.length, "Length mismatch");

        for (uint256 i = 0; i < jobs.length; i++) {
            bytes32 jobHash = _hashJob(jobs[i]);
            require(!executedJobs[jobHash], "Already executed");
            require(block.timestamp <= jobs[i].deadline, "Expired");

            // Verify the worker signature
            address signer = jobHash.toEthSignedMessageHash().recover(signatures[i]);
            require(authorizedWorkers[signer], "Unauthorized worker");
            require(jobs[i].nonce == nonces[signer], "Invalid nonce");

            nonces[signer]++;
            executedJobs[jobHash] = true;

            // Derive execution authorization token
            bytes32 authToken = _deriveJobKey(i);

            // Execute with auth token embedded in call
            (bool success, ) = jobs[i].target.call{value: jobs[i].value}(
                abi.encodePacked(jobs[i].payload, authToken)
            );

            emit JobExecuted(jobHash, signer, success);
        }
    }

    function verifyAuthToken(bytes32 token, uint256 jobIndex) external view returns (bool) {
        // Called by target contracts to verify the job was authorized
        return token == _deriveJobKey(jobIndex);
    }

    function _hashJob(Job calldata job) internal view returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                "\x19\x01",
                DOMAIN_SEPARATOR,
                keccak256(abi.encode(
                    JOB_TYPEHASH,
                    job.target,
                    keccak256(job.payload),
                    job.value,
                    job.deadline,
                    job.nonce
                ))
            )
        );
    }

    function addWorker(address worker) external onlyOwner {
        authorizedWorkers[worker] = true;
    }

    function removeWorker(address worker) external onlyOwner {
        authorizedWorkers[worker] = false;
    }

    function updateRelayer(address newRelayer) external onlyOwner {
        relayerAddress = newRelayer;
    }

    receive() external payable {}
}
